import React, { useState } from 'react';
import { ChevronDown, Sparkles, CheckCircle2, ExternalLink, MapPin, Clock, ShieldCheck, BarChart3, Sparkle, Info, HelpCircle, MoreHorizontal } from 'lucide-react';

const faqItems = [
  {
    id: 1,
    title: "How can I order pizza for delivery?",
    content: "Visit our online ordering form and select 'Delivery'. Enter your address and choose your desired pizza size and toppings. Payments are securely processed via Stripe."
  },
  {
    id: 2,
    title: "Do you offer any vegan or vegetarian options?",
    content: "Absolutely! Our menu features a variety of vegan and vegetarian dishes, including the Margherita pizza with fresh heirloom tomatoes, mozzarella di buffalo, and basil. Check our full menu for more options."
  },
  {
    id: 3,
    title: "What types of natural wines do you serve?",
    content: "We curate a selection of low-intervention, organic wines from small producers in Italy and the Mediterranean. Our sommelier can recommend pairings with your meal or wine flights."
  },
  {
    id: 4,
    title: "How far in advance should I book a table?",
    content: "For peak dining hours (18:00-21:00), we recommend booking at least 24 hours in advance. For dinner reservations, you can book up to 7 days ahead. Walk-ins are welcome, but availability is limited."
  },
  {
    id: 5,
    title: "What payment methods do you accept?",
    content: "We accept cash, all major credit cards (Visa, Mastercard, American Express), and contactless mobile payments. Digital wallets like Apple Pay and Google Pay are also supported."
  },
  {
    id: 6,
    title: "Are your pizzas made from scratch?",
    content: "Yes, our wood-fired pizzas are crafted daily with fresh ingredients. We use stone-ground flour for the dough and locally sourced toppings whenever possible. See our daily specials for today’s offerings."
  }
];

export default function Faq() {
  const [isOpen, setIsOpen] = useState(false);

  return (
    <div className="w-full max-w-6xl mx-auto p-6 sm:p-8 bg-white/5 rounded-2xl border border-white/10 shadow-2xl backdrop-blur-xl text-slate-200 font-sans">
      <div className="pb-10 border-b border-white/10">
        <div className="flex flex-col sm:flex-row justify-between items-center mb-8">
          <div>
            <div className="text-xl sm:text-2xl font-bold text-amber-400 flex items-center gap-2">
              <Sparkles className="w-5 h-5 animate-pulse" />
              <span>Frequently Asked Questions</span>
            </div>
            <p className="text-sm text-slate-400 mt-2 max-w-md">
              Get the answers to common questions about ordering, dining, and our wine selection.
            </p>
          </div>
          <button
            onClick={() => setIsOpen(!isOpen)}
            className="flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-white/5 border border-white/10 text-slate-500 hover:text-white hover:bg-white/10 transition-colors duration-200"
          >
            {isOpen ? <span className="text-xl"> ítens fechados</span> : <span className="text-xl"> ítens abertos</span>} <ChevronDown className="w-3 h-3" />
          </button>
        </div>
        <div className="space-y-6 sm:space-y-0 sm:grid sm:grid-cols-2 sm:gap-6">
          {faqItems.map((item) => (
            <div
              key={item.id}
              className="transition-all duration-300 hover:shadow-2xl hover:scale-[1.02] group"
            >
              <div className="py-4 sm:py-6 bg-white/5 border-b border-white/10">
                <button
                  className="flex items-center justify-between w-full p-4 sm:p-6 rounded-t-xl text-left text-slate-400 transition-colors duration-200 hover:text-slate-100"
                  onClick={() => setIsOpen(!isOpen)}
                >
                  <div className="flex items-center space-x-2">
                    <div className="w-2.5 h-2.5 rounded-full bg-amber-500/20 group-hover:bg-amber-500/30" />
                    <div className="w-2.5 h-2.5 rounded-full bg-amber-500/20 group-hover:bg-amber-500/30" />
                    <div className="w-2.5 h-2.5 rounded-full bg-amber-500/20 group-hover:bg-amber-500/30" />
                    <span className="text-base sm:text-xl font-medium tracking-wide">{item.title}</span>
                  </div>
                  <ChevronDown className="w-5 h-5 text-slate-500 group-active:text-slate-400" />
                </button>
              </div>
              {isOpen && (
                <div className="py-4 sm:py-6 bg-white/5 border-t border-white/10">
                  <p className="text-sm sm:text-base text-slate-400">{item.content}</p>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
